        {
            return;
        }

        var target = Directory.Exists(item.Path)
            ? item.Path
            : Path.GetDirectoryName(item.Path) ?? item.Path;
        Process.Start(new ProcessStartInfo
        {
            FileName = "explorer.exe",
            Arguments = $"\"{target}\"",
            UseShellExecute = true
        });
    }

