    private async Task<List<ConvertFixReportItem>> BuildConvertFixThemeTestReportAsync(string packagePath)
    {
        var inspection = await InspectConvertFixTemplateAsync(packagePath);
        try
        {
            var layers = inspection.Layers.Where(layer => !layer.IsEditorMetadata).ToList();
            var backgroundLayer = layers.FirstOrDefault(layer =>
                string.Equals(layer.Type, "GraphAnimation", StringComparison.OrdinalIgnoreCase));
            var backgroundReference = FirstNonEmpty(
                backgroundLayer?.Media ?? "",
                backgroundLayer?.MediaPath ?? "",
                inspection.Manifest?.BackgroundFile ?? "",
                inspection.Manifest?.background ?? "");
            var items = new List<ConvertFixReportItem>
            {
                new() { Label = "File", Value = inspection.PackagePath, Severity = "Header" },
                new() { Label = "Template", Value = inspection.TemplateEntryName, Severity = "Header" },
                new() { Label = "Device", Value = FirstNonEmpty(inspection.DeviceModel, "(unknown)") },
                new() { Label = "Template ID", Value = FirstNonEmpty(inspection.Manifest?.TemplateId ?? "", Path.GetFileNameWithoutExtension(inspection.TemplateEntryName)) },
                new() { Label = "Layers", Value = layers.Count.ToString(CultureInfo.InvariantCulture) },
                new() { Label = "Background", Value = FirstNonEmpty(backgroundReference, "(none)") },
                new()
                {
                    Label = "Asset",
                    Value = DescribeConvertFixPackageReference(inspection, backgroundReference),
                    Severity = DescribeConvertFixPackageReference(inspection, backgroundReference).StartsWith("missing", StringComparison.OrdinalIgnoreCase)
                        ? "Warning"
                        : "Info"
                },
                new()
                {
                    Label = "Preview",
                    Value = DescribeConvertFixPackageReference(inspection, inspection.Manifest?.PreviewFile ?? ""),
                    Severity = DescribeConvertFixPackageReference(inspection, inspection.Manifest?.PreviewFile ?? "").StartsWith("missing", StringComparison.OrdinalIgnoreCase)
                        ? "Warning"
                        : "Info"
                },
                new() { Label = "Fonts", Value = GetConvertFixLayerFontNames(layers).Count.ToString(CultureInfo.InvariantCulture) }
            };

            if (!Path.GetExtension(packagePath).Equals(".template", StringComparison.OrdinalIgnoreCase))
            {
                var validation = _themeValidator.Validate(
                    packagePath,
                    TemplateOptions.Select(option => option.Id),
                    inspection.DeviceModel);
                foreach (var issue in validation.Issues)
                {
                    items.Add(new ConvertFixReportItem
                    {
                        Label = issue.Severity,
                        Value = issue.Message,
                        Severity = issue.Severity
                    });
                }
            }

            return items;
        }
        finally
        {
            TryDeleteDirectory(inspection.TempRoot);
        }
    }

    private async Task ScanConvertFixFontsAsync(string packagePath)
    {
        FontControlFontList.ItemsSource = null;
        FontControlStatusText.Text = "No package selected.";

        if (string.IsNullOrWhiteSpace(packagePath) || !File.Exists(packagePath))
        {
            return;
        }

        try
        {
            var inspection = await InspectConvertFixTemplateAsync(packagePath);
            var fonts = BuildConvertFixFontItems(inspection);
            FontControlFontList.ItemsSource = fonts;
            FontControlStatusText.Text = fonts.Count == 0
                ? "No font usage found in template layers."
                : $"Found {fonts.Count} font family reference(s) in template layers. Use Dafont to find missing fonts, then select the font and choose the downloaded .ttf/.otf file.";
        }
        catch (Exception ex)
        {
            AppLogger.Error("Convert & Fix font scan failed.", ex);
            FontControlStatusText.Text = $"Font scan failed: {ex.Message}";
        }
    }

    private async Task<ConvertFixTemplateInspection> InspectConvertFixTemplateAsync(string packagePath)
    {
        var tempRoot = Path.Combine(
            Path.GetTempPath(),
            "LianLiThemeEditor",
            "ConvertFixInspection",
            Path.GetFileNameWithoutExtension(packagePath) + "-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tempRoot);
        var packageEntries = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var packagedFonts = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var templateEntryName = Path.GetFileName(packagePath);
        var templatePath = packagePath;
        ThemePackageManifest? manifest = null;

        if (!Path.GetExtension(packagePath).Equals(".template", StringComparison.OrdinalIgnoreCase))
        {
            using var archive = ZipFile.OpenRead(packagePath);
            manifest = ReadPackageManifest(archive);
            foreach (var entry in archive.Entries.Where(entry => !string.IsNullOrWhiteSpace(entry.Name)))
            {
                packageEntries[entry.FullName.Replace('\\', '/')] = entry.FullName;
            }

            var templateEntry = !string.IsNullOrWhiteSpace(manifest?.TemplateFile)
                ? TryGetPackageEntry(archive, manifest.TemplateFile)
                : null;
            templateEntry ??= archive.Entries.FirstOrDefault(entry =>
                entry.Name.EndsWith(".template", StringComparison.OrdinalIgnoreCase));
            if (templateEntry == null)
            {
                throw new InvalidDataException("No .template file was found in the selected package.");
            }

            templateEntryName = templateEntry.FullName;
            templatePath = Path.Combine(tempRoot, GetSafeFileName(templateEntry.Name));
            templateEntry.ExtractToFile(templatePath, true);

            foreach (var fontEntry in archive.Entries.Where(IsFontPackageEntry))
            {
                var target = Path.Combine(tempRoot, "fonts", GetSafeFileName(fontEntry.Name));
                Directory.CreateDirectory(Path.GetDirectoryName(target)!);
                fontEntry.ExtractToFile(target, true);
                var family = ReadFontFamilyName(target);
                if (!packagedFonts.ContainsKey(family))
                {
                    packagedFonts[family] = target;
                }
                var normalizedFamily = NormalizeFontLookupKey(family);
                if (!string.IsNullOrWhiteSpace(normalizedFamily) && !packagedFonts.ContainsKey(normalizedFamily))
                {
                    packagedFonts[normalizedFamily] = target;
                }
                var fileName = Path.GetFileNameWithoutExtension(fontEntry.Name);
                if (!packagedFonts.ContainsKey(fileName))
                {
                    packagedFonts[fileName] = target;
                }
                var normalizedFileName = NormalizeFontLookupKey(fileName);
                if (!string.IsNullOrWhiteSpace(normalizedFileName) && !packagedFonts.ContainsKey(normalizedFileName))
                {
                    packagedFonts[normalizedFileName] = target;
                }
            }
        }

        var deviceModel = FirstNonEmpty(
            manifest?.DeviceModel ?? "",
            manifest?.deviceModel ?? "",
            InferConvertFixDeviceModelFromPackage(packagePath, templateEntryName),
            GetSelectedDeviceModel());
        var result = await Task.Run(() => _supporter.LoadTemplatePathAsync(deviceModel, templatePath));
        if (manifest == null)
        {
            manifest = new ThemePackageManifest
            {
                DeviceModel = deviceModel,
                TemplateId = result.TemplateId,
                TemplateFile = templateEntryName
            };
        }

        return new ConvertFixTemplateInspection
        {
            PackagePath = packagePath,
            TemplatePath = templatePath,
            TemplateEntryName = templateEntryName,
            DeviceModel = deviceModel,
            Manifest = manifest,
            Layers = result.Layers,
            PackageEntries = packageEntries,
            PackagedFonts = packagedFonts,
            TempRoot = tempRoot
        };
    }

    private static ThemePackageManifest? ReadPackageManifest(ZipArchive archive)
    {
        var manifestEntry = archive.GetEntry("manifest.json");
        if (manifestEntry == null)
        {
            return null;
        }

        using var reader = new StreamReader(manifestEntry.Open(), System.Text.Encoding.UTF8);
        var manifest = JsonSerializer.Deserialize<ThemePackageManifest>(reader.ReadToEnd());
        if (manifest != null)
        {
            NormalizeThemePackageManifest(manifest);
        }

        return manifest;
    }

    private static string DescribePackageEntry(ZipArchive archive, string? entryName)
    {
        if (string.IsNullOrWhiteSpace(entryName))
        {
            return "not declared";
        }

        var entry = TryGetPackageEntry(archive, entryName);
        return entry == null ? $"missing ({entryName})" : $"ok ({entry.FullName}, {entry.Length:N0} bytes)";
    }

    private static List<ConvertFixFontItem> BuildConvertFixFontItems(ConvertFixTemplateInspection inspection)
    {
        return GetConvertFixLayerFontNames(inspection.Layers)
            .Select(font =>
            {
                var sourcePath = ResolvePackagedFontPath(inspection.PackagedFonts, font.Name);
                return new ConvertFixFontItem
                {
                    Source = font.Source,
                    ExtractedPath = "",
                    FamilyName = font.Name,
                    InstalledMachineWide = IsFontInstalledMachineWide(font.Name, Path.GetFileName(sourcePath)),
                    InstallSelected = !IsFontInstalledMachineWide(font.Name, Path.GetFileName(sourcePath))
                };
            })
            .OrderBy(item => item.InstalledMachineWide)
            .ThenBy(item => item.FamilyName, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private static List<(string Name, string Source)> GetConvertFixLayerFontNames(IEnumerable<LayerRow> layers)
    {
        var fonts = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var layer in layers.Where(layer => !layer.IsEditorMetadata))
        {
            foreach (var candidate in GetLayerFontCandidates(layer))
            {
                var font = ResolveCanonicalFontName(candidate);
                if (string.IsNullOrWhiteSpace(font))
                {
                    continue;
                }

                var source = $"#{layer.Index} {FirstNonEmpty(layer.TypeDisplay, layer.Type)}";
                if (fonts.TryGetValue(font, out var existing))
                {
                    if (!existing.Contains(source, StringComparison.OrdinalIgnoreCase))
                    {
                        fonts[font] = existing + ", " + source;
                    }
                }
                else
                {
                    fonts[font] = source;
                }
            }
        }

        return fonts.Select(item => (item.Key, item.Value)).ToList();
    }

    private static IEnumerable<string> GetLayerFontCandidates(LayerRow layer)
    {
        if (!string.IsNullOrWhiteSpace(layer.Font))
        {
            yield return layer.Font;
        }

        if (!string.IsNullOrWhiteSpace(layer.SensorFontFamily))
        {
            yield return layer.SensorFontFamily;
        }
    }

    private static string ResolvePackagedFontPath(IReadOnlyDictionary<string, string> packagedFonts, string fontName)
    {
        if (string.IsNullOrWhiteSpace(fontName))
        {
            return "";
        }

        return packagedFonts.TryGetValue(fontName, out var path) ||
               packagedFonts.TryGetValue(NormalizeFontLookupKey(fontName), out path)
            ? path
            : "";
    }

    private static string DescribeConvertFixPackageReference(ConvertFixTemplateInspection inspection, string? reference)
    {
        if (string.IsNullOrWhiteSpace(reference))
        {
            return "not declared";
        }

        if (File.Exists(reference))
        {
            return $"external file exists ({reference})";
        }

        var normalized = reference.Replace('\\', '/').TrimStart('/');
        if (inspection.PackageEntries.ContainsKey(normalized))
        {
            return $"ok ({normalized})";
        }

        var fileName = Path.GetFileName(normalized);
        var match = inspection.PackageEntries.Keys.FirstOrDefault(entry =>
            string.Equals(Path.GetFileName(entry), fileName, StringComparison.OrdinalIgnoreCase));
        return string.IsNullOrWhiteSpace(match)
            ? $"missing ({reference})"
            : $"ok ({match})";
    }

    private static string InferConvertFixDeviceModelFromPackage(string packagePath, string templateEntryName)
    {
        var text = $"{packagePath} {templateEntryName}";
        if (text.Contains("8.8", StringComparison.OrdinalIgnoreCase) ||
            text.Contains("universal", StringComparison.OrdinalIgnoreCase) ||
            text.Contains("vertical", StringComparison.OrdinalIgnoreCase) ||
            text.Contains("landscape", StringComparison.OrdinalIgnoreCase) ||
            text.Contains("portrait", StringComparison.OrdinalIgnoreCase))
        {
            return UniversalScreenDeviceModel;
        }

        if (text.Contains("vm92", StringComparison.OrdinalIgnoreCase) ||
            text.Contains("9.2", StringComparison.OrdinalIgnoreCase))
        {
            return Vm92DeviceModel;
        }

        if (text.Contains("lcd-c", StringComparison.OrdinalIgnoreCase))
        {
            return "hydroshift-ii-lcd-c";
        }

        if (text.Contains("lcd-s", StringComparison.OrdinalIgnoreCase))
        {
            return "hydroshift-ii-lcd-s";
        }

        return "";
    }

    private static bool IsFontPackageEntry(ZipArchiveEntry entry) =>
        !string.IsNullOrWhiteSpace(entry.Name) && IsFontFilePath(entry.Name);

    private static bool IsFontFilePath(string path)
    {
        var extension = Path.GetExtension(path);
        return extension.Equals(".ttf", StringComparison.OrdinalIgnoreCase) ||
               extension.Equals(".otf", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsMediaPackageEntry(string path)
    {
        var extension = Path.GetExtension(path);
        return extension.Equals(".mp4", StringComparison.OrdinalIgnoreCase) ||
               extension.Equals(".h264", StringComparison.OrdinalIgnoreCase) ||
               extension.Equals(".gif", StringComparison.OrdinalIgnoreCase) ||
               extension.Equals(".png", StringComparison.OrdinalIgnoreCase) ||
               extension.Equals(".jpg", StringComparison.OrdinalIgnoreCase) ||
               extension.Equals(".jpeg", StringComparison.OrdinalIgnoreCase) ||
               extension.Equals(".webp", StringComparison.OrdinalIgnoreCase);
    }

    private static string ReadFontFamilyName(string fontPath)
    {
        try
        {
            var typeface = new GlyphTypeface(new Uri(fontPath, UriKind.Absolute));
            return typeface.Win32FamilyNames.TryGetValue(CultureInfo.GetCultureInfo("en-us"), out var englishName)
                ? englishName
                : typeface.Win32FamilyNames.Values.FirstOrDefault()
                  ?? Path.GetFileNameWithoutExtension(fontPath);
        }
        catch
        {
            return Path.GetFileNameWithoutExtension(fontPath);
        }
    }

    private static bool IsFontInstalledMachineWide(string fontName, string fileName)
    {
        foreach (var view in GetRegistryViews())
        {
            try
            {
                using var baseKey = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, view);
                using var fontsKey = baseKey.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts");
                if (fontsKey == null)
                {
                    continue;
                }

                foreach (var name in fontsKey.GetValueNames())
                {
                    var value = fontsKey.GetValue(name)?.ToString() ?? "";
                    if (FontRegistryNameMatches(name, fontName) ||
                        value.Equals(fileName, StringComparison.OrdinalIgnoreCase) ||
                        Path.GetFileName(value).Equals(fileName, StringComparison.OrdinalIgnoreCase))
                    {
                        return true;
                    }
                }
            }
            catch
            {
            }
        }

        return false;
    }

    private bool ShowThemeValidation(ThemeValidationResult validation)
    {
        var panel = new StackPanel { Margin = new Thickness(20), Width = 560 };
        panel.Children.Add(new TextBlock { Text = GetLanguageText("validation.title", "Theme package check"), FontSize = 18, FontWeight = FontWeights.SemiBold });
        panel.Children.Add(new TextBlock { Text = $"{validation.TemplateId}  |  {validation.DeviceModel}", Margin = new Thickness(0, 5, 0, 12), Foreground = (Brush)FindResource("BrTextTertiary") });
        foreach (var issue in validation.Issues)
        {
            var color = issue.Severity.Equals("Error", StringComparison.OrdinalIgnoreCase) ? "#E05A67" : issue.Severity.Equals("Warning", StringComparison.OrdinalIgnoreCase) ? "#F0B84B" : "#62D6B5";
            panel.Children.Add(new TextBlock { Text = $"{issue.Severity}: {issue.Message}", Foreground = (Brush)new BrushConverter().ConvertFromString(color)!, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 3, 0, 3) });
        }
        var buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
        var cancel = new Button { Content = GetLanguageText("common.cancel", "Cancel"), Width = 90, IsCancel = true };
        var proceed = new Button { Content = GetLanguageText("validation.continue", "Continue"), Width = 90, IsDefault = true, Margin = new Thickness(8, 0, 0, 0), IsEnabled = validation.IsValid };
        buttons.Children.Add(cancel); buttons.Children.Add(proceed); panel.Children.Add(buttons);
        var window = new Window { Owner = this, Content = panel, Title = GetLanguageText("validation.windowTitle", "Validate theme"), SizeToContent = SizeToContent.WidthAndHeight, WindowStartupLocation = WindowStartupLocation.CenterOwner, ResizeMode = ResizeMode.NoResize, ShowInTaskbar = false };
        proceed.Click += (_, _) => window.DialogResult = true;
        return window.ShowDialog() == true;
    }

    private async void CheckUpdatesButton_Click(object sender, RoutedEventArgs e)
    {
        CheckUpdatesButton.IsEnabled = false;
        UpdateStatusText.Text = GetLanguageText("updates.checking", "Checking GitHub releases...");
        try
        {
            var json = await SharedHttpClient.GetStringAsync(GitHubLatestReleaseApiUrl);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;
            var latestName = GetJsonString(root, "name");
            var latestTag = GetJsonString(root, "tag_name", latestName);
            var releaseUrl = GetJsonString(root, "html_url", GitHubReleasesUrl);
            var currentVersion = GetAppDisplayVersion();

            if (LooksLikeSameVersion(currentVersion, latestTag) ||
                LooksLikeSameVersion(currentVersion, latestName))
            {
                UpdateStatusText.Text = FormatLanguageText("updates.current", "You are up to date. Current version: {0}.", currentVersion);
                SetStatus(GetLanguageText("updates.noUpdate", "No update found."));
                return;
            }

            UpdateStatusText.Text = FormatLanguageText("updates.latestFound", "Latest release: {0}. Current version: {1}.", latestTag, currentVersion);
            var result = MessageBox.Show(
                this,
                FormatLanguageText("updates.openReleasePrompt", "Latest release: {0}\nCurrent version: {1}\n\nOpen the release page?", latestTag, currentVersion),
                GetLanguageText("updates.availableTitle", "Update available"),
                MessageBoxButton.YesNo,
                MessageBoxImage.Information);
            if (result == MessageBoxResult.Yes)
            {
                OpenExternalUrl(releaseUrl);
            }
        }
        catch (Exception ex)
        {
            UpdateStatusText.Text = FormatLanguageText("updates.failed", "Could not check updates: {0}", ex.Message);
            var result = MessageBox.Show(
                this,
                GetLanguageText("updates.failedPrompt", "The automatic check could not reach GitHub releases. Open the releases page instead?"),
                GetLanguageText("updates.failedTitle", "Update check failed"),
                MessageBoxButton.YesNo,
                MessageBoxImage.Information);
            if (result == MessageBoxResult.Yes)
            {
                OpenExternalUrl(GitHubReleasesUrl);
            }
        }
        finally
        {
            CheckUpdatesButton.IsEnabled = true;
        }
    }

    private static void OpenExternalUrl(string url)
    {
        try
        {
            Process.Start(new ProcessStartInfo
            {
                FileName = url,
                UseShellExecute = true
            });
        }
        catch
        {
        }
    }

    private static string GetAppDisplayVersion()
    {
        var assembly = typeof(MainWindow).Assembly;
        var informational = assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion;
        if (!string.IsNullOrWhiteSpace(informational))
        {
            return informational;
        }

        return assembly.GetName().Version?.ToString() ?? "Unknown";
    }

    private string GetAppBuildDisplayText()
    {
        return FormatLanguageText("app.versionBuildFormat", "Version {0}  |  Built {1}", GetAppDisplayVersion(), BuildInfo.BuiltAt);
    }

    private void UpdateAppVersionChrome()
    {
        var version = GetAppDisplayVersion();
        Title = FormatLanguageText("window.titleFormat", "Lian Li LCD Template Editor {0}", version);
        if (HeaderVersionText != null)
        {
            HeaderVersionText.Text = version;
        }
    }

    private static bool LooksLikeSameVersion(string currentVersion, string latestVersion)
    {
        var current = NormalizeVersionLabel(currentVersion);
        var latest = NormalizeVersionLabel(latestVersion);
        return !string.IsNullOrWhiteSpace(current) &&
               !string.IsNullOrWhiteSpace(latest) &&
               string.Equals(current, latest, StringComparison.OrdinalIgnoreCase);
    }

    private static string NormalizeVersionLabel(string version)
    {
        return Regex.Replace(version ?? "", @"[^0-9a-z]+", "", RegexOptions.IgnoreCase)
            .ToLowerInvariant()
            .TrimStart('v');
    }

    private async void GalleryDownloadButton_Click(object sender, RoutedEventArgs e)
    {
        e.Handled = true;
        if ((sender as Button)?.CommandParameter is not GalleryThemeItem item || item.IsBusy)
        {
            return;
        }

        var downloadKey = GetGalleryDownloadKey(item);
        if (_recentGalleryDownloads.TryGetValue(downloadKey, out var lastDownloadUtc) &&
            DateTime.UtcNow - lastDownloadUtc < TimeSpan.FromSeconds(5))
        {
            return;
        }
        if (!_activeGalleryDownloads.Add(downloadKey))
        {
            return;
        }

        item.IsBusy = true;
        try
        {
            if (await DownloadAndInstallGalleryThemeAsync(item, GalleryActivateAfterInstallCheck.IsChecked == true))
            {
                _recentGalleryDownloads[downloadKey] = DateTime.UtcNow;
            }
        }
        finally
        {
            _activeGalleryDownloads.Remove(downloadKey);
        }
    }

    private static string GetGalleryDownloadKey(GalleryThemeItem item)
    {
        var packageName = GetGalleryPackageFileBaseName(item.PackageUrl);
        if (!string.IsNullOrWhiteSpace(packageName))
        {
            return $"{item.DeviceModel}|{SanitizeFileName(packageName)}";
        }

        if (!string.IsNullOrWhiteSpace(item.PackageUrl))
        {
            return $"{item.DeviceModel}|{item.PackageUrl.Trim()}";
        }

        return $"{item.DeviceModel}|{SanitizeFileName(item.Id)}";
    }

