    private void RefreshLayerDataSourceDisplay(LayerRow layer)
    {
        layer.DataSourceDisplay = string.IsNullOrWhiteSpace(layer.DataSource)
            ? ""
            : GetDataSourceDisplayName(layer.DataSource);
